        D := R * 0.627;
        p5 := Pi/5;

        function GetInt(): integer;
        begin
          p := Pos(',', sSplits);
          if p = 0 then begin
            substr := sSplits;
            sSplits := '';
          end else begin
            substr := copy(sSplits, 1, p-1);
            Delete(sSplits, 1, p);
          end;
          Result := StrToInt(Trim(substr));
        end;

        procedure GetSplits();
        begin
          pCount := 0;
          while Length(sSplits) > 0 do begin
            Splits[pCount] := GetInt;
            Inc(pCount);
          end;
        end;

